{
  "options": [
    {
      "id": "A",
      "name": "Dynamic PK Sub-visits and Granular Forms",
      "summary": "Build the 7 PK subgroup visits as dynamic events triggered by PK substudy consent, decompose Mayo forms into individual subscores, and add dedicated forms for ADA, Diary, Weight, and Chest X-ray.",
      "pros": [
        "Mirrors the protocol schedule of assessments 1-to-1 with explicit visits V2.1–V2.3, V7.1–V7.3, and V8.1.",
        "Dynamic event rules hide the 7 PK visits for non-PK subjects, keeping the subject matrix clean for sites.",
        "Capturing individual Mayo subscores (stool frequency, rectal bleeding, endoscopy, PGA) enables exact derivation and validation of modified Mayo, PGA change, and FDA-defined remission."
      ],
      "cons": [
        "Higher build and testing effort due to 7 new events, dynamic trigger rules, and multiple new forms.",
        "Updates required across existing edit checks and SDV review plans to cover the new PK sub-visits."
      ],
      "tradeoff": "This option gives sites a visit schedule that matches the protocol table and keeps non-PK casebooks clean through dynamic rules. It costs extra build and validation time to set up seven new events and their triggers.",
      "recommended": true
    },
    {
      "id": "B",
      "name": "Consolidated PK Visits and Embedded Items",
      "summary": "Keep the existing 11-event schedule by logging 48h, 144h, and 240h PK samples on parent visits V2, V7, and V8, while embedding new assessment items into existing forms wherever possible.",
      "pros": [
        "No changes to the event schedule, avoiding dynamic visit rules and event-level migration issues.",
        "Fewer new forms by embedding TB modality/chest X-ray into TB, endoscopy subscore into ENDO, and AESI into AE."
      ],
      "cons": [
        "Deviates from the protocol visit numbering (V2.1–V8.1), which can confuse sites and monitors tracking visit-specific windows.",
        "Requires multi-timepoint data entry on single PK forms at V2, V7, and V8 across different calendar days."
      ],
      "tradeoff": "This option avoids adding seven new events to the schedule by rolling all post-dose PK timepoints into their parent visits. It costs clarity for site staff who expect separate folders for the dedicated PK follow-up days.",
      "recommended": false
    },
    {
      "id": "C",
      "name": "Static PK Sub-visits with Form-level Gating",
      "summary": "Add V2.1–V8.1 as standard non-dynamic events for all subjects using form-level gating items, and add standalone forms for each new protocol assessment.",
      "pros": [
        "Avoids complex dynamic event rules while still providing explicit visit folders matching the protocol schedule.",
        "Standalone forms for AESI, ADA, Diary, and Weight isolate new protocol requirements from existing verified forms."
      ],
      "cons": [
        "Clutters the casebook matrix for non-PK subjects with 7 unused visit folders.",
        "Creating separate forms for AESI and modified Mayo duplicates context that naturally belongs on the AE and MAYO/PMAYO forms."
      ],
      "tradeoff": "This option provides dedicated folders for every PK visit without relying on dynamic event rules. It clutters the casebook with seven empty visits for every patient who does not join the PK substudy.",
      "recommended": false
    }
  ]
}
